    "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated\" // ใช้ Path นี้ตามที่กำหนดไว้\n}\n\ndatasource db {\n  provider = \"mysql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// --- Enums ---\n\nenum Role {\n  user\n  admin\n}\n\nenum RegistrationType {\n  individual\n  school\n}\n\nenum IndividualStatus {\n  registered\n  slip_uploaded\n  verified\n  exam_ready\n  completed\n}\n\nenum QuestionType {\n  text\n  radio\n  checkbox\n}\n\n// --- Models ---\n\n// User Model\nmodel User {\n  id         String  @id @default(cuid())\n  name       String\n  email      String  @unique\n  password   String\n  role       Role    @default(user)\n  phone      String?\n  department String?\n  bio        String? @db.Text\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  individualRegistrations IndividualRegistration[]\n  surveyResponses         SurveyResponse[]\n}\n\n// Individual Registration Model (ตัวหลัก)\nmodel IndividualRegistration {\n  id String @id @default(cuid())\n\n  fullname String\n  grade    String\n  school   String\n  phone    String\n  email    String\n\n  stationName String\n\n  userCode  String @unique\n  adminCode String\n\n  status IndividualStatus @default(registered)\n\n  slipUrl        String?\n  certificateUrl String?\n\n  // Relationships\n  event   Event  @relation(fields: [eventId], references: [id])\n  eventId String // Foreign Key\n\n  user   User   @relation(fields: [userId], references: [id])\n  userId String // Foreign Key\n\n  createdAt DateTime @default(now())\n}\n\n// Station Model\nmodel Station {\n  id          String @id @default(cuid())\n  stationName String\n  address     String\n  capacity    Int\n  code        Int\n\n  // Relationship\n  event   Event  @relation(fields: [eventId], references: [id])\n  eventId String // Foreign Key\n}\n\n// Event Model\nmodel Event {\n  id          String   @id @default(cuid())\n  nameEvent   String\n  detail      String?  @db.Text\n  dateAndTime DateTime\n  location    String?\n  images      String?\n  levels      Json?\n\n  registrationType RegistrationType @default(individual)\n  code             String\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relationships\n  stations                Station[]\n  individualRegistrations IndividualRegistration[]\n  surveyResponses         SurveyResponse[]\n  solutions               Solution[]\n}\n\n// Survey Question Model\nmodel SurveyQuestion {\n  id       String       @id @default(cuid())\n  question String\n  type     QuestionType @default(text)\n  options  Json // แก้เป็น Json\n\n  // Relationship\n  survey   Survey @relation(fields: [surveyId], references: [id])\n  surveyId String // Foreign Key\n}\n\n// Survey Model\nmodel Survey {\n  id String @id @default(cuid())\n\n  eventId String @unique // Unique Constraint\n\n  title    String  @default(\"แบบสอบถามหลังสอบ\")\n  isActive Boolean @default(false)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relationships\n  questions       SurveyQuestion[]\n  surveyResponses SurveyResponse[]\n}\n\n// Survey Answer Model\nmodel SurveyAnswer {\n  id            String @id @default(cuid())\n  questionIndex Int\n  question      String\n  answer        Json // แก้เป็น Json\n\n  // Relationship\n  response   SurveyResponse @relation(fields: [responseId], references: [id])\n  responseId String // Foreign Key\n}\n\n// Survey Response Model\nmodel SurveyResponse {\n  id       String @id @default(cuid())\n  userCode String\n\n  // Relationships\n  survey   Survey @relation(fields: [surveyId], references: [id])\n  surveyId String // Foreign Key\n\n  event   Event  @relation(fields: [eventId], references: [id])\n  eventId String // Foreign Key\n\n  user   User   @relation(fields: [userId], references: [id])\n  userId String // Foreign Key\n\n  // Relationship (Back)\n  answers SurveyAnswer[]\n\n  // Timestamps\n  submittedAt DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  // Composite Unique Index\n  @@unique([surveyId, userId])\n}\n\n// Certificate Model\nmodel Certificate {\n  id             String   @id @default(cuid())\n  userCode       String\n  eventId        String\n  certificateUrl String\n  uploadedAt     DateTime @default(now())\n\n  // Composite Unique Index\n  @@unique([userCode, eventId])\n}\n\n// Counter Model\nmodel Counter {\n  id   String @id @default(cuid())\n  name String @unique\n  seq  Int    @default(0)\n}\n\n// Solution Model\nmodel Solution {\n  id         String   @id @default(cuid())\n  event      Event    @relation(fields: [eventId], references: [id])\n  eventId    String\n  fileUrl    String\n  uploadedAt DateTime @default(now())\n}\n\n// Landing Content Model (Singleton)\nmodel LandingContent {\n  id             Int    @id @default(1)\n  historyTitle   String\n  historyContent String @db.Text\n  objectiveTitle String\n  objectives     Json // แก้เป็น Json\n}\n",
